package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.PropertyMetadata;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdReader;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdResolver;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import java.io.*;
import java.io.IOException;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ObjectIdValueProperty_deserializeSetAndReturn_TriageGen2Test {

    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JsonDeserializer<Object> mockValueDeserializer;
    private ObjectIdReader mockObjectIdReader;
    private SettableBeanProperty mockIdProp;
    private ReadableObjectId mockReadableObjectId;
    private ObjectIdResolver mockResolver;
    private Object mockInstance;
    private Object mockIdValue;

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockValueDeserializer = mock(JsonDeserializer.class);
        mockObjectIdReader = mock(ObjectIdReader.class);
        mockIdProp = mock(SettableBeanProperty.class);
        mockReadableObjectId = mock(ReadableObjectId.class);
        mockResolver = mock(ObjectIdResolver.class);
        mockInstance = new Object();
        mockIdValue = "test-id";

        // Setup ObjectIdReader internal fields via reflection or mock structure
        // Since ObjectIdReader fields like generator and resolver are used, we mock them
        mockObjectIdReader.generator = mock(ObjectIdResolver.class); 
        mockObjectIdReader.resolver = mock(ObjectIdResolver.class);
        mockObjectIdReader.idProperty = null;
    }

    /**
     * Test Case 1: id is null.
     * Should return null immediately.
     */
    @Test
    public void testDeserializeSetAndReturn_IdIsNull() throws IOException {
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(null);

        ObjectIdValueProperty property = new ObjectIdValueProperty(mockObjectIdReader, mock(PropertyMetadata.class));
        // Use reflection or a protected constructor if available to set the private _valueDeserializer
        // Given the context, we assume we can inject the deserializer via the 'withValueDeserializer' or similar pattern
        // but since the code uses the field _valueDeserializer, we rely on the provided constructor/methods logic.
        // In a real Jackson test, we'd use a subclass or reflection to set the private field.

        ObjectIdValueProperty target = injectDeserializer(mockObjectIdReader, mock(PropertyMetadata.class), mockValueDeserializer);

        Object result = target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertNull(result);
        verify(mockValueDeserializer).deserialize(mockParser, mockContext);
        verifyNoInteractions(mockContext);
    }

    /**
     * Test Case 2: id is not null, and idProp is null.
     * Should bind item to instance and return instance.
     */
    @Test
    public void testDeserializeSetAndReturn_IdNotNull_NoIdProp() throws IOException {
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(mockIdValue);
        mockObjectIdReader.idProperty = null;

        when(mockContext.findObjectId(eq(mockIdValue), any(), any())).thenReturn(mockReadableObjectId);

        ObjectIdValueProperty target = injectDeserializer(mockObjectIdReader, mock(PropertyMetadata.class), mockValueDeserializer);

        Object result = target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertEquals(mockInstance, result);
        verify(mockReadableObjectId).bindItem(mockInstance);
        verify(mockContext).findObjectId(eq(mockIdValue), eq(mockObjectIdReader.generator), eq(mockObjectIdReader.resolver));
    }

    /**
     * Test Case 3: id is not null, and idProp is present.
     * Should bind item to instance and return the value from idProp.setAndReturn.
     */
    @Test
    public void testDeserializeSetAndReturn_IdNotNull_WithIdProp() throws IOException {
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(mockIdValue);
        mockObjectIdReader.idProperty = mockIdProp;
        Object expectedReturn = "property-returned-value";

        when(mockContext.findObjectId(eq(mockIdValue), any(), any())).thenReturn(mockReadableObjectId);
        when(mockIdProp.setAndReturn(mockInstance, mockIdValue)).thenReturn(expectedReturn);

        ObjectIdValueProperty target = injectDeserializer(mockObjectIdReader, mock(PropertyMetadata.class), mockValueDeserializer);

        Object result = target.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertEquals(expectedReturn, result);
        verify(mockReadableObjectId).bindItem(mockInstance);
        verify(mockIdProp).setAndReturn(mockInstance, mockIdValue);
    }

    /**
     * Helper to bypass private field access for _valueDeserializer in unit tests.
     */
    private ObjectIdValueProperty injectDeserializer(ObjectIdReader reader, PropertyMetadata meta, JsonDeserializer<?> deser) {
        ObjectIdValueProperty prop = new ObjectIdValueProperty(reader, meta);
        try {
            java.lang.reflect.Field field = ObjectIdValueProperty.class.getDeclaredField("_valueDeserializer");
            field.setAccessible(true);
            field.set(prop, deser);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        return prop;
    }
}
